// swift-tools-version: 6.0
import PackageDescription

// VectorCraftBridge.xcframework and Sources/VectorCraftKit/vectorcraft_apple.swift are generated by
// apple/scripts/build-xcframework.sh (gitignored). Run it before opening the project.
let package = Package(
    name: "VectorCraftKit",
    platforms: [.iOS("26.0")],
    products: [
        .library(name: "VectorCraftKit", targets: ["VectorCraftKit"]),
    ],
    targets: [
        .binaryTarget(name: "VectorCraftBridge", path: "VectorCraftBridge.xcframework"),
        .target(
            name: "VectorCraftKit",
            dependencies: ["VectorCraftBridge"],
            swiftSettings: [.swiftLanguageMode(.v5)],  // UniFFI-generated code is not Swift 6 strict-concurrency clean
            // The static engine library needs the C++ runtime and zlib, and its dependencies link these system
            // frameworks (fonts through CoreText, file handling, networking-free but std pulls Security).
            linkerSettings: [
                .linkedLibrary("c++"), .linkedLibrary("z"),
                .linkedFramework("CoreFoundation"), .linkedFramework("CoreGraphics"), .linkedFramework("CoreText"),
                .linkedFramework("Foundation"), .linkedFramework("Security"), .linkedFramework("SystemConfiguration"),
            ]
        ),
    ]
)
